action GET_rroomsay_signeddidsignoncetext___room_say_signed(room: str, did: str, text: str, nonce: int, budgetAvailable: bool, staleRace: bool, seq: int): bool = {
  val entry = rooms.get(room)
  val existedBefore = entry.exists
  val charged = not(existedBefore)
  val core = applyAppendCore(entry, textLen(text), Some(did), Some(nonce), staleRace, ringLimit)
  val appendOk = canAppendCore(entry, existingCount, totalBytes, Some(did), Some(nonce))
  val actuallyCreated = appendOk and core.seq == 1
  val updated = { ...core, createdViaHttp: entry.createdViaHttp or actuallyCreated, httpWriteCount: entry.httpWriteCount + 1 }
  all {
    textLen(text) > 0,
    textLen(text) <= MAX_TEXT_CHARS_MODEL,
    writeAllowed(room, entry, Some(did)),
    not(charged) or budgetAvailable,
    seq == nextSeq(entry, staleRace),
    rooms' = if (appendOk) rooms.set(room, updated) else rooms,
    refundsIssued' = if (appendOk and charged and not(actuallyCreated)) refundsIssued + 1 else refundsIssued,
    totalCharged' = if (charged) totalCharged + 1 else totalCharged,
  }
}

// POST /r/{room} -> room_post — mutates, JSON body, optional signature (app.py:1170).
// Split into two sibling actions (unsigned / signed) rather than one action with an
// Option[str]-typed `signer` parameter: the oracle's replay engine does not pin a logged
// JSON `null` to `None` for an Option-typed argument — it treats it the same as an
// omitted argument, leaving `signer` (and everything derived from it) an unresolvable
// wildcard search. Both actions are routed from the SAME logged event name via
// actionNameMap, matching exactly _payload_credentials' branch (app.py:1118-1123).

action room_post_unsigned(room: str, nick: str, text: str, budgetAvailable: bool, staleRace: bool, seq: int): bool = {
  val entry = rooms.get(room)
  val existedBefore = entry.exists
  val charged = not(existedBefore)
  val core = applyAppendCore(entry, textLen(text), None, None, staleRace, ringLimit)
  val appendOk = canAppendCore(entry, existingCount, totalBytes, None, None)
  val actuallyCreated = appendOk and core.seq == 1
  val updated = { ...core, createdViaHttp: entry.createdViaHttp or actuallyCreated, httpWriteCount: entry.httpWriteCount + 1 }
  all {
    isValidNick(nick),
    textLen(text) > 0,
    textLen(text) <= MAX_TEXT_CHARS_MODEL,
    writeAllowed(room, entry, None),
    not(charged) or budgetAvailable,
    seq == nextSeq(entry, staleRace),
    rooms' = if (appendOk) rooms.set(room, updated) else rooms,
    refundsIssued' = if (appendOk and charged and not(actuallyCreated)) refundsIssued + 1 else refundsIssued,
    totalCharged' = if (charged) totalCharged + 1 else totalCharged,
  }
}

action room_post_signed(room: str, did: str, text: str, nonce: int, budgetAvailable: bool, staleRace: bool, seq: int): bool = {
  val entry = rooms.get(room)
  val existedBefore = entry.exists
  val charged = not(existedBefore)
  val core = applyAppendCore(entry, textLen(text), Some(did), Some(nonce), staleRace, ringLimit)
  val appendOk = canAppendCore(entry, existingCount, totalBytes, Some(did), Some(nonce))
  val actuallyCreated = appendOk and core.seq == 1
  val updated = { ...core, createdViaHttp: entry.createdViaHttp or actuallyCreated, httpWriteCount: entry.httpWriteCount + 1 }
  all {
    textLen(text) > 0,
    textLen(text) <= MAX_TEXT_CHARS_MODEL,
    writeAllowed(room, entry, Some(did)),
    not(charged) or budgetAvailable,
    seq == nextSeq(entry, staleRace),
    rooms' = if (appendOk) rooms.set(room, updated) else rooms,
    refundsIssued' = if (appendOk and charged and not(actuallyCreated)) refundsIssued + 1 else refundsIssued,
    totalCharged' = if (charged) totalCharged + 1 else totalCharged,
  }
}

