  // --------------------------------------------------------------------- properties

  /// The server-only events room is never written by an external HTTP caller, regardless
  /// of signature — forging a `created <room>` announcement there would steer every agent
  /// watching /r/events into a room of the attacker's choosing (app.py:941-955).
  val events_room_immutable: bool =
    rooms.get(EVENTS_ROOM).httpWriteCount == 0

  /// A room's on-disk ring never exceeds the hard per-room byte ceiling — compaction always
  /// brings it back under the limit before the write that crossed it returns, so no single
  /// room can run the disk out from under every other room sharing the budget.
  val no_room_overflow: bool =
    ROOMS.forall(r => rooms.get(r).bytesUsed <= MAX_ROOM_BYTES_MODEL)

  /// Every creation charge nets to zero unless it belongs to the request that actually
  /// created the room (seq==1): a losing racer, or a charged request whose append itself
  /// was then refused, must not permanently cost the caller a slot in their daily
  /// room-creation budget (app.py:306-336).
  val create_budget_conserved: bool =
    totalCharged - refundsIssued == ROOMS.filter(r => rooms.get(r).createdViaHttp).size()

  /// For every DID that has written into a room with a signature, its accepted nonces
  /// strictly increase over time — the guarantee that makes a captured signed URL rejected
  /// as a replay rather than accepted as a second, forged message under that DID's
  /// identity. (This model keeps unbounded per-did memory, a deliberately STRICTER
  /// simplification of store.py's bounded-tail-window lookback — see nonceGuard.)
  val nonce_strictly_increasing: bool =
    ROOMS.forall(r => DIDS.forall(d => isStrictlyIncreasing(rooms.get(r).nonceHistory.get(d))))

  /// The cached last-nonce-per-did (what the guard actually checks against) always agrees
  /// with the full nonce history it was derived from — a redundant-representation check
  /// that would catch an update that bumped one and not the other.
  val nonce_history_consistent: bool =
    ROOMS.forall(r => DIDS.forall(d => {
      val h = rooms.get(r).nonceHistory.get(d)
      val last = rooms.get(r).lastNonceByDid.get(d)
      if (h.length() == 0) last == -1 else last == h.nth(h.length() - 1)
    }))

  // --------------------------------------------------------------------- observations

  /// An external HTTP write brought a brand-new room into existence and was billed for it.
  val room_created_via_http: bool =
    ROOMS.exists(r => rooms.get(r).createdViaHttp)

  /// A charged request lost the creation race (or its append then failed) and its charge
  /// was refunded.
  val create_charge_refunded: bool =
    refundsIssued > 0

  /// A room's ring crossed its byte budget and was compacted down to the retained half.
  val room_ring_compacted: bool =
    ROOMS.exists(r => rooms.get(r).everCompacted)

  /// The service-wide room budget is exhausted, so new rooms are held to the smaller
  /// reserved-per-room floor instead of the full ring.
  val reserved_floor_in_effect: bool =
    totalBytes >= MAX_TOTAL_ROOM_BYTES_MODEL

  /// A write to an owned room landed from an allow-listed key that is not the owner itself.
  val owned_room_write_by_allowlisted_key: bool =
    ROOMS.exists(r => {
      val e = rooms.get(r)
      e.owner != None and (if (e.lastWriterDid == None) false else {
        val w = unwrap(e.lastWriterDid)
        e.allow.contains(w) and Some(w) != e.owner
      })
    })

  /// A signed write was accepted into a mailbox-class room.
  val mailbox_signed_write_landed: bool =
    rooms.get("mb-inbox").exists and rooms.get("mb-inbox").lastWriterDid != None

  /// A room exists on disk but no HTTP request is credited with creating it — either the
  /// bare store-level `append` created it directly, or an HTTP request lost the creation
  /// race and a later, un-refunded request's write landed as if it had won.
  val room_exists_without_http_creation_credit: bool =
    ROOMS.exists(r => rooms.get(r).exists and not(rooms.get(r).createdViaHttp))
}

