// classifies `did`'s shape with its OWN independent re-implementation of public_key's
// guard chain (see didkey.py's `_did_slot`) and separately records whether the REAL
// call raised. The guard below ties them together, so a real regression that lets
// public_key() succeed (or fail) against its documented guard chain — without touching
// the DID string's actual shape — fails replay instead of silently matching.
action public_key(did: str, ok: bool): bool = all {
  ok == publicKeyOk(did),
  st' = { ...st, publicKeyLast: Some(didShapeOf(did)) },
}

// is_did(value) — didkey.py:71. A pure shape predicate, never proof of ownership; also
// used on plain nicknames (app.py:107,111), not only on things claiming to be DIDs.
// `result` is the same kind of conformance fact as `public_key`'s `ok` — the real
// returned boolean, checked against the independently classified shape.
action is_did(value: str, result: bool): bool = all {
  result == isDidPure(value),
  st' = { ...st, isDidLast: Some({ value: value, result: result }) },
}

// abbreviate(did) — didkey.py:81. The docstring/every call site (app.py:610,1089,1622)
// trusts the caller already checked is_did(did) first; the function body itself performs
// NO check. That is a documented-but-unenforced precondition (component-map
// adversarySurface row 1) — modeled here as a guard even though didkey.py doesn't

def _signer(did: str, sig: str, nonce: str, canonical: str) -> str | Response:
    """Verify one signed write. Returns the DID it was signed by, or the refusal.

    The signature covers client-controlled input only — `room|nonce|text` for a message,
    `ns|key|nonce|value` for a note — because the agent cannot know `seq` or `ts` at
    signing time (§5.2). It covers the text *after* the single-line sweep, i.e. exactly
    the bytes that get stored: signing the raw input would leave a stored record nobody
    could re-verify. `room`, `ns`, `key` and `nonce` cannot contain the separator, and the
    free-form field is last, so the canonical string parses one way only.
    """
    if not NONCE_RE.fullmatch(nonce):
        return text(f"400 nonce must be 1-19 digits, got {nonce!r}", 400)
    try:
        didkey.verify(did, sig, canonical)
    except didkey.DidError as exc:
        return text(f"400 {exc}", 400)
    except didkey.SignatureError:
        return text(
            f"403 signature does not verify for {did}.\n"
            f"it must cover exactly this string, UTF-8, Ed25519, base64url:\n{canonical}",
            403,
        )
    return did

